const inventory=await fetch('./API-INVENTORY.json').then(r=>{if(!r.ok)throw new Error('接口清单加载失败');return r.json()});
let ui;const state={query:'',group:'全部模块',page:1};
const groups=[...new Set(inventory.endpoints.map(r=>r.group))];
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderCapabilities(h){ui=h;return `<div class="page capabilities"><div class="page-heading"><div><div class="eyebrow">FUNCTION MAP / FRONTEND ↔ BACKEND</div><h1>每项能力，都有明确位置。</h1><p>接口存在、页面承接和待补设计分别列出，方便逐项核对。</p></div><a class="btn" href="API-COVERAGE.md" target="_blank">完整检查报告 ↗</a></div><div class="coverage-summary"><div><strong>${inventory.routeFiles}</strong><small>API 路由文件</small></div><div><strong>${inventory.endpoints.length}</strong><small>HTTP 方法入口</small></div><div><strong>${inventory.serverExports.length}</strong><small>server 导出函数</small></div><div><strong>${inventory.gaps.length}</strong><small>差距与补充设计</small></div></div><p class="backend-note">工作区静态代码快照 · 页面列表示设计承接位置 · 已有接口尚未在原型联调 · 内部函数不自动新增接口</p><div class="coverage-tools"><input id="coverage-search" type="search" aria-label="搜索功能或接口" placeholder="搜索模块、接口路径或后端函数…" value="${escape(state.query)}"><select id="coverage-group" aria-label="筛选功能模块">${['全部模块',...groups].map(g=>`<option ${g===state.group?'selected':''}>${g}</option>`).join('')}</select><a class="btn" href="#teardown">查看视频拆解完整链路 →</a></div><div id="coverage-list">${rows()}</div><div class="section-heading" style="margin-top:36px"><h2>缺口与补充设计 <span>GAPS & CONTRACTS</span></h2></div><div class="coverage-gaps">${inventory.gaps.map((g,i)=>`<article class="coverage-gap"><span class="badge">${g.status}</span><h3>${g.title}</h3><p>${g.reason}</p><button class="btn" data-coverage-gap="${i}" style="margin-top:16px">查看补充设计 →</button></article>`).join('')}</div>${h.footer()}</div>`}
function filtered(){return inventory.endpoints.filter(r=>(state.group==='全部模块'||state.group===r.group)&&`${r.path} ${r.group} ${r.placement} ${r.calls.map(c=>c.name).join(' ')}`.toLowerCase().includes(state.query.toLowerCase()))}
function rows(){const all=filtered(),pages=Math.max(1,Math.ceil(all.length/20));state.page=Math.min(state.page,pages);return `<div class="coverage-table"><div class="coverage-row coverage-head"><span>方法</span><span>后端接口</span><span>前端承接位置</span><span>操作设计</span></div>${all.slice((state.page-1)*20,state.page*20).map(r=>`<div class="coverage-row"><span class="badge">${r.method}</span><div><code>${escape(r.path)}</code><small>${r.group} · ${r.status}</small></div><a href="#${r.page}">${r.placement} ↗</a><button class="btn" data-coverage-id="${escape(r.id)}">查看对应设计</button></div>`).join('')||'<div class="empty">没有匹配的接口</div>'}<div class="coverage-pagination"><button class="btn" data-coverage-page="-1" ${state.page===1?'disabled':''}>上一页</button><span>${all.length} 项 / ${state.page} 页，共 ${pages} 页</span><button class="btn" data-coverage-page="1" ${state.page===pages?'disabled':''}>下一页</button></div></div>`}
function repaint(){document.querySelector('#coverage-list').innerHTML=rows()}
const settingGroups=[{title:'AI 与外部服务',group:'设置与偏好',text:'模型、采集与转录能力统一配置。测试连接、启用与禁用使用已有接口。',icon:'spark'},{title:'空间与成员',group:'设置与偏好',text:'工作空间、成员、邀请和角色。只读、管理员及所有者权限由服务端判断。',icon:'folder'},{title:'系统管理与用量',group:'系统管理员',text:'用户、工作空间、系统 Provider 与用量；仅供系统管理员。',icon:'settings'},{title:'账号与登录',group:'登录与账号',text:'登录、验证、邀请与恢复。产品登录账号与创作者平台账号分开。',icon:'help'},{title:'存储与运行状态',group:'基础能力与内部入口',text:'存储选择、诊断、队列和服务健康。内部媒体授权不暴露为普通用户操作。',icon:'file'},{title:'兼容流程',group:'项目与成果',text:'历史母稿、平台稿与 Canvas 在兼容范围内保留，入口不改变项目主线。',icon:'book'}];
export function renderSettings(h){ui=h;return `<div class="page"><div class="page-heading"><div><div class="eyebrow">WORKSPACE / SETTINGS</div><h1>让工作环境，准备就绪。</h1><p>配置、权限和运行状态集中管理，创作页面保持简洁。</p></div><a class="btn" href="#capabilities">功能与接口地图 →</a></div><div class="backend-context"><span class="badge">设置页面设计预览</span><span>不读取密钥、不修改成员、不变更存储</span></div><div class="settings-grid">${settingGroups.map((g,i)=>`<section class="settings-card">${h.icon(g.icon)}<h2>${g.title}</h2><p>${g.text}</p><button class="btn" data-settings-group="${i}">查看操作与接口 →</button></section>`).join('')}</div>${h.footer()}</div>`}
document.addEventListener('input',e=>{if(e.target.id==='coverage-search'){state.query=e.target.value;state.page=1;repaint()}});
document.addEventListener('change',e=>{if(e.target.id==='coverage-group'){state.group=e.target.value;state.page=1;repaint()}});
document.addEventListener('click',e=>{const t=e.target.closest('[data-coverage-id],[data-coverage-gap],[data-coverage-page],[data-settings-group]');if(!t||!ui)return;
if(t.dataset.coveragePage){state.page+=Number(t.dataset.coveragePage);repaint();return}
if(t.dataset.settingsGroup){const g=settingGroups[Number(t.dataset.settingsGroup)];state.group=g.group;state.query=g.title==='兼容流程'?'mother-content':'';state.page=1;location.hash='capabilities';return}
if(t.dataset.coverageGap!==undefined){const g=inventory.gaps[Number(t.dataset.coverageGap)];ui.modal(g.title,`<p class="dialog-copy">${escape(g.reason)}</p><div class="td-report-note">${escape(g.proposal)}</div><p class="backend-note">此项是设计或待核对能力，未实现新 API。</p>`,`<a class="btn" href="#${g.page}" data-action="close">查看页面承接</a>`);return}
const r=inventory.endpoints.find(r=>r.id===t.dataset.coverageId);if(!r)return;const mutating=!['GET','HEAD','OPTIONS'].includes(r.method);
ui.modal('功能与操作对应',`<span class="badge">${r.status}</span><h3 style="margin:18px 0;font-size:15px;overflow-wrap:anywhere">${escape(r.id)}</h3><p class="dialog-copy">模块：${r.group}<br>页面：${r.placement}<br>操作：${mutating?'用户主动触发；写入前核对范围与版本，返回结果后更新状态。':'页面读取；按范围获取，展示加载、空态与失败。'}</p><div class="td-report-note">${mutating?'设计状态：准备输入 → 提交中 → 成功 / 校验失败 / 无权限 / 版本冲突。':'设计状态：加载中 → 有数据 / 无数据 / 无权限 / 读取失败。'}<br>当前只展示操作设计，不发送该请求。</div><p class="backend-note">源码：${escape(r.source)}:${r.line}<br>直接调用：${r.calls.map(c=>escape(c.name)).join('、')||'处理器内实现或转发'}<br>${r.verification}<br>已找到 action：${r.bodyActions?.map(escape).join("、")||"按该处理器契约输入"}</p>`,`<a class="btn primary" href="#${r.page}" data-action="close">打开对应页面 →</a>`);
});
